DIs│// 轻量 API 客户端：共享访问密钥（ADR-0002）存 localStorage，请求自动带 Authorization: Bearer。
AuN│
60o│const KEY_STORAGE = "kanso.accessKey";
71p│
CXZ│// UNAUTHORIZED_EVENT 在任一 API 返回 401 时广播，路由守卫据此清除登录态并回登录页。
FRq│export const UNAUTHORIZED_EVENT = "kanso:unauthorized";
GSr│
bru│export function getAccessKey(): string | null {
mr4│	return localStorage.getItem(KEY_STORAGE);
AU6│}
BV7│
JVQ│export function setAccessKey(key: string): void {
iU6│	localStorage.setItem(KEY_STORAGE, key);
jV7│}
kW8│
xVn│export function clearAccessKey(): void {
nwk│	localStorage.removeItem(KEY_STORAGE);
oxl│}
pym│
7M0│// verifyAccessKey 校验用户输入的访问密钥（登录页专用，不携带本地密钥）。
X5T│export async function verifyAccessKey(key: string): Promise<boolean> {
YqX│	try {
YJD│		const res = await fetch("/api/auth/verify", {
19t│			method: "POST",
FC7│			headers: { "Content-Type": "application/json" },
Dct│			body: JSON.stringify({ key }),
AI7│		});
hoH│		return res.ok;
mx4│	} catch {
ZPk│		return false;
vKS│	}
wLT│}
xMU│
CP2│export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
LvE│	const key = getAccessKey();
aQ5│	const res = await fetch(path, {
4gI│		...init,
s34│		headers: {
Nb9│			"Content-Type": "application/json",
QeB│			...(key ? { Authorization: `Bearer ${key}` } : {}),
pPU│			...init.headers,
bB4│		},
FmF│	});
SO3│	if (!res.ok) {
SF7│		// 401 = 密钥失效/未认证，清除本地密钥并广播，由路由守卫引导回登录页
fE5│		if (res.status === 401) {
Ovv│			clearAccessKey();
T2A│			window.dispatchEvent(new Event(UNAUTHORIZED_EVENT));
zUu│		}
5DI│		throw new Error(`API ${res.status}: ${path}`);
A4s│	}
H5r│	if (res.status === 204) {
B5u│		return undefined as T;
6EJ│	}
GZn│	return res.json() as Promise<T>;
93r│}

